var n=`0384-hutspot`;var i=`world-0384`;var a=`NL`;var o=`western-europe`;var l=4;var r=48;var s={en:`Hutspot`,ua:`Гютспот`};var u={en:`Dutch hutspot with mashed vegetables and cooked bratwurst in place of a traditional smoked sausage.`,ua:`Нідерландський гютспот із овочевим пюре та приготованим братвурстом замість традиційної копченої ковбаси.`};var m=[{en:`Cook the listed ingredients in simmering water for about 24 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 24 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:24,i:[[`potato`,850,`g`],[`carrot`,430,`g`],[`yellow-onion`,270,`g`],[`water`,1150,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:6,i:[[`unsalted-butter`,95,`g`],[`whole-cow-milk`,190,`ml`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Simmer the bratwurst gently until fully cooked and the center registers a safe temperature; slice and place over the hot vegetable mash.`,ua:`Варіть братвурст на слабкому вогні до повної готовності та безпечної внутрішньої температури; наріжте й викладіть на гаряче овочеве пюре.`,t:[`simmering`],m:18,i:[[`bratwurst`,430,`g`]]}];var d={slug:n,id:i,country:`NL`,region:o,servings:4,minutes:48,title:s,text:u,steps:m};export{a as country,d as default,i as id,r as minutes,o as region,l as servings,n as slug,m as steps,u as text,s as title};